package com.example.discovery.consumer.service;import static org.assertj.core.api.Assertions.*;import com.example.discovery.consumer.client.RegistryClient;import com.example.discovery.consumer.config.ConsumerProperties;import com.example.discovery.consumer.model.ServiceInstance;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.Mockito;import org.springframework.web.client.RestClient;class PaymentServiceTest{@Test void throwsWhenNoInstances(){var registry=Mockito.mock(RegistryClient.class);Mockito.when(registry.discover()).thenReturn(List.of());var service=new PaymentService(registry,new RoundRobinLoadBalancer(),RestClient.builder().build(),new ConsumerProperties("payment-service","http://registry"));assertThatThrownBy(service::getPayments).isInstanceOf(ServiceUnavailableException.class).hasMessage("No available instances for payment-service");}@Test void failoverThrows503DomainExceptionWhenAllFail(){var registry=Mockito.mock(RegistryClient.class);Mockito.when(registry.discover()).thenReturn(List.of(new ServiceInstance("payment-service","bad-1","localhost",1,"",null,null,"UP"),new ServiceInstance("payment-service","bad-2","localhost",2,"",null,null,"UP")));var service=new PaymentService(registry,new RoundRobinLoadBalancer(),RestClient.builder().build(),new ConsumerProperties("payment-service","http://registry"));assertThatThrownBy(service::getPayments).isInstanceOf(ServiceUnavailableException.class);}}
